const config = $input.all()[0].json;
return [{
  json: {
    endpoint: config.forestWeatherEndpoint,
    generatedAt: config.generatedAt,
  }
}];

const checkedAt = new Date().toISOString();
const config = $items('Set Connector Config')[0].json;
const departments = JSON.parse(config.departmentsJson);
const departmentByCode = new Map(departments.map((d) => [d.code, d]));
const requestedDepartmentCodes = JSON.parse(config.requestedDepartmentCodesJson);
const targetCodes = new Set(requestedDepartmentCodes);

const inputItems = $input.all();
if (!inputItems.length) {
  return [{ json: { recordKind: 'wildfireDepartmentForecastMeta', fetchOk: false, classification: 'SOURCE_API_BLOCKED', error: 'No response reached the fetch node', elevatedRecordCount: 0 } }];
}
const raw = inputItems[0].json || {};
const status = Number(raw.statusCode || 0);
const bodyText = String(raw.body !== undefined ? raw.body : (raw.data !== undefined ? raw.data : ''));

if (status === 401 || status === 403) {
  return [{ json: { recordKind: 'wildfireDepartmentForecastMeta', fetchOk: false, classification: 'CREDENTIALS_BLOCKED', httpStatus: status, error: 'Météo-France forest-weather request rejected the bound credential (401/403). Never logging the response body.', elevatedRecordCount: 0 } }];
}
if (!status || status < 200 || status >= 300 || !bodyText) {
  return [{ json: { recordKind: 'wildfireDepartmentForecastMeta', fetchOk: false, classification: 'SOURCE_API_BLOCKED', httpStatus: status || 0, error: 'Météo-France forest-weather request failed or returned an empty body.', elevatedRecordCount: 0 } }];
}

const severityByDangerCode = { '1': 'green', '2': 'yellow', '3': 'orange', '4': 'red', faible: 'green', vert: 'green', low: 'green', modere: 'yellow', 'modéré': 'yellow', jaune: 'yellow', moderate: 'yellow', eleve: 'orange', 'élevé': 'orange', orange: 'orange', high: 'orange', 'tres-eleve': 'red', 'très-élevé': 'red', 'tres eleve': 'red', 'très élevé': 'red', rouge: 'red', red: 'red', 'very high': 'red' };
const labelBySeverity = { green: 'Low', yellow: 'Moderate', orange: 'High', red: 'Very high' };

function normalizeDepartmentCode(value) {
  const code = String(value ?? '').trim();
  return /^\d$/.test(code) ? `0${code}` : code;
}
function normalizeSeverity(value) {
  const key = String(value ?? '').trim().toLowerCase();
  return severityByDangerCode[key] ?? null;
}
function normalizeForecastDay(value) {
  const key = String(value ?? '').trim().toLowerCase();
  if (/^(2|j2|d\+?2|lendemain)$/.test(key)) return 'D+2';
  return 'D+1';
}
function forecastDayLongLabel(value) { return value === 'D+2' ? 'following day (D+2)' : 'tomorrow (D+1)'; }
function forestWeatherExplanation(severity, departmentName, forecastDay) {
  const when = forecastDayLongLabel(forecastDay);
  return {
    yellow: `Official Météo-France forest-weather data shows yellow fire danger for ${departmentName} ${when}, meaning fires start more easily in dry vegetation.`,
    orange: `Official Météo-France forest-weather data shows orange fire danger for ${departmentName} ${when}, indicating elevated wildfire-start and spread risk.`,
    red: `Official Météo-France forest-weather data shows red fire danger for ${departmentName} ${when}, indicating very high wildfire-start and spread risk today.`,
  }[severity] || null;
}

function parseDelimited(text) {
  const lines = text.trim().split(/\r?\n/).filter(Boolean);
  const headers = lines.shift()?.split(';').map((h) => h.trim()) ?? [];
  return lines.map((line) => {
    const values = line.split(';');
    return Object.fromEntries(headers.map((h, idx) => [h, values[idx]?.trim() ?? '']));
  });
}

function findDepartmentRisks(value, records = []) {
  if (!value || typeof value !== 'object') return records;
  if (Array.isArray(value)) { value.forEach((item) => findDepartmentRisks(item, records)); return records; }
  const departmentCode = normalizeDepartmentCode(value.code_departement ?? value.department_code ?? value.department ?? value.domain_id ?? value.code ?? value.dept);
  const day = value.echeance ?? value.day ?? value.jour ?? value.validity_day ?? value.valid_day ?? value.date_echeance;
  const danger = value.niveau_danger ?? value.danger_level ?? value.risk_level ?? value.risk_code ?? value.color_id ?? value.niveau ?? value.couleur;
  const severity = normalizeSeverity(danger);
  if (departmentByCode.has(departmentCode) && severity) {
    records.push({ departmentCode, day: normalizeForecastDay(day), severity, referenceTime: value.date_validation ?? value.date_echeance ?? value.reference_time ?? value.update_time ?? value.date_maj ?? null });
  }
  Object.values(value).forEach((item) => findDepartmentRisks(item, records));
  return records;
}

let risks;
try {
  const payload = JSON.parse(bodyText);
  risks = findDepartmentRisks(payload);
} catch (err) {
  const rows = parseDelimited(bodyText);
  risks = rows.flatMap((row) => {
    const departmentCode = normalizeDepartmentCode(row.dep_code);
    if (!departmentByCode.has(departmentCode)) return [];
    return [
      { departmentCode, day: 'D+1', severity: normalizeSeverity(row.niveau_j1), referenceTime: row.reference_time },
      { departmentCode, day: 'D+2', severity: normalizeSeverity(row.niveau_j2), referenceTime: row.reference_time },
    ].filter((r) => r.severity);
  });
}

const dedupedRisks = Array.from(risks.reduce((items, risk) => {
  if (!targetCodes.has(risk.departmentCode) || !risk.severity) return items;
  const key = [risk.departmentCode, risk.day, risk.severity, risk.referenceTime ?? ''].join('|');
  if (!items.has(key)) items.set(key, risk);
  return items;
}, new Map()).values());

const wildfireRiskRecords = [];
for (const risk of dedupedRisks) {
  const department = departmentByCode.get(risk.departmentCode);
  if (!department || !department.rideDays.length) continue;
  if (risk.severity === 'green') continue;
  const explanation = forestWeatherExplanation(risk.severity, department.name, risk.day);
  for (const rideDay of department.rideDays) {
    wildfireRiskRecords.push({
      json: {
        recordKind: 'wildfireRisk',
        externalId: `meteo-france-forest-weather-${risk.departmentCode}-${risk.day}-${risk.severity}-${rideDay}`,
        sourceId: 'meteo-france-forest-weather',
        category: 'wildfire',
        semanticStatus: 'forest_fire_risk',
        officialRiskLevel: labelBySeverity[risk.severity],
        officialRiskColor: risk.severity,
        severity: risk.severity,
        status: 'forecast',
        title: `${labelBySeverity[risk.severity]} fire danger in ${department.name} (${forecastDayLongLabel(risk.day)}).`,
        nearestPlace: department.name,
        departmentCode: risk.departmentCode,
        departmentName: department.name,
        rideDay,
        distanceFromRouteKm: null,
        routeInfluenceConfirmed: true,
        startTime: risk.referenceTime || checkedAt,
        expectedEndTime: null,
        checkedAt,
        sourceUrl: config.sourceUrl,
        summary: `${department.name} has a ${labelBySeverity[risk.severity].toLowerCase()} department-level forest fire danger forecast for ${risk.day}.`,
        statusTitle: `${labelBySeverity[risk.severity]} fire danger in ${department.name} (${forecastDayLongLabel(risk.day)}).`,
        statusExplanation: explanation,
        statusSource: { name: 'Météo-France Météo des Forêts', url: config.sourceUrl, official: true, checkedAt, sourceLanguage: 'fr', translationMethod: 'condensed_official_source' },
        whyItMatters: 'The official fire-danger forecast applies at department level and overlaps one or more planned riding days.',
        recommendedAction: 'Check official guidance and local restrictions before riding through the affected department.',
        suggestedDetour: null,
        detourImpact: null,
      }
    });
  }
}

const meta = { json: { recordKind: 'wildfireDepartmentForecastMeta', fetchOk: true, httpStatus: status, dedupedRiskCount: dedupedRisks.length, elevatedRecordCount: wildfireRiskRecords.length } };

return [...wildfireRiskRecords, meta];

const checkedAt = new Date().toISOString();
const config = $items('Set Connector Config')[0].json;
const inputItems = $input.all();
const raw = (inputItems[0] && inputItems[0].json) || {};
const status = Number(raw.statusCode || 0);
const bodyText = String(raw.body !== undefined ? raw.body : (raw.data !== undefined ? raw.data : ''));

let recordCount = 0;
try {
  const metaItems = $items('Normalize Wildfire Risk Records');
  const meta = metaItems.find((i) => i.json.recordKind === 'wildfireDepartmentForecastMeta');
  if (meta) recordCount = meta.json.elevatedRecordCount || 0;
} catch (err) {
  // Normalize node may not have produced items if the fetch failed upstream.
}

let healthStatus;
const errors = [];
const warnings = [];
if (status === 401 || status === 403) {
  healthStatus = 'credentials_blocked';
  errors.push('Météo-France forest-weather request rejected the bound credential (401/403).');
} else if (!status || status < 200 || status >= 300 || !bodyText) {
  healthStatus = 'failed';
  errors.push(`Météo-France forest-weather request failed (httpStatus=${status || 0}).`);
} else {
  healthStatus = 'ok';
}

return [{
  json: {
    recordKind: 'sourceHealth',
    sourceId: 'meteo-france-forest-weather',
    sourceName: 'Météo-France Météo des Forêts',
    status: healthStatus,
    fetchedAt: checkedAt,
    staleAfterMinutes: Number(config.staleAfterMinutes),
    httpStatus: status || 0,
    recordCount,
    errors,
    warnings,
  }
}];

const config = $items('Set Connector Config')[0].json;
const allInputs = [];
for (const name of ['Normalize Wildfire Risk Records', 'Build Source Health']) {
  try { allInputs.push(...$items(name).map((i) => i.json || {})); } catch (err) {}
}

function validIso(v) { return !v || !Number.isNaN(Date.parse(v)); }
function looksLikeSecret(v) { if (typeof v !== 'string') return false; return /^[A-Za-z0-9_-]{24,}$/.test(v) && !/^https?:\/\//.test(v); }
const severityEnum = ['green', 'yellow', 'orange', 'red'];
const forbiddenPathPattern = /(^|\/)(tmp|data\/public|home\/node\/\.n8n)(\/|$)/i;

const errors = [];
const warnings = [];

if (!config.connectorId) errors.push('Missing connectorId in Set Connector Config');
if (!config.connectorNumber) errors.push('Missing connectorNumber in Set Connector Config');
if (!config.workflowName) errors.push('Missing workflowName in Set Connector Config');
if (!config.workflowVersion) errors.push('Missing workflowVersion in Set Connector Config');
if (!validIso(config.generatedAt)) errors.push('Missing or invalid generatedAt in Set Connector Config');
if (!config.outputDirectory || !config.outputDirectory.startsWith('/files/cdm-status-output')) errors.push('Forbidden or missing output directory: expected /files/cdm-status-output');
if (forbiddenPathPattern.test(config.outputDirectory || '')) errors.push('Output directory matches a forbidden path pattern');
if (!config.attributionText) errors.push('Missing attribution text');

const fullText = JSON.stringify(allInputs);
if (/bearer\s+[A-Za-z0-9_\-.]{20,}/i.test(fullText)) errors.push('Possible bearer token leaked into merged output records');
if (/apikey["']?\s*[:=]\s*["'][A-Za-z0-9_\-]{16,}["']/i.test(fullText)) errors.push('Possible hardcoded API key value leaked into merged output records');
if (fullText.toLowerCase().includes('meteofrance_forest_weather_api_key') && /[:=]\s*["'][A-Za-z0-9_\-]{16,}["']/i.test(fullText)) errors.push('Possible hardcoded credential value leaked into merged output records');
if (/process\.env/.test(fullText)) errors.push('process.env literal found in merged output records');
if (/route\s+closure|active\s+wildfire|active\s+fire|smoke\s+impact|air[\s-]?quality\s+impact/i.test(fullText)) {
  errors.push('Merged output appears to claim route closure, active wildfire, or smoke/air-quality impact, which this connector must never assert');
}

let sawSourceHealth = false;
for (const r of allInputs) {
  if (r.recordKind === 'sourceHealth') {
    sawSourceHealth = true;
    for (const field of ['sourceId', 'sourceName', 'status', 'fetchedAt', 'staleAfterMinutes', 'httpStatus', 'recordCount', 'errors', 'warnings']) {
      if (r[field] === undefined || r[field] === null) errors.push(`sourceHealth ${r.sourceId || 'unknown'} missing ${field}`);
    }
    if (!validIso(r.fetchedAt)) errors.push(`sourceHealth ${r.sourceId} has invalid fetchedAt`);
    if (!['ok', 'degraded', 'failed', 'stale', 'credentials_blocked'].includes(r.status)) errors.push(`sourceHealth ${r.sourceId} has invalid status enum: ${r.status}`);
    continue;
  }
  if (r.recordKind === 'wildfireRisk') {
    for (const field of ['externalId', 'sourceId', 'category', 'severity', 'status', 'title', 'checkedAt', 'departmentCode', 'rideDay']) {
      if (r[field] === undefined || r[field] === null || r[field] === '') errors.push(`wildfireRisk/${r.externalId || 'unknown'}: missing required field ${field}`);
    }
    if (r.severity && !severityEnum.includes(r.severity)) errors.push(`wildfireRisk/${r.externalId}: invalid severity enum ${r.severity}`);
    if (!validIso(r.checkedAt) || !validIso(r.startTime)) errors.push(`wildfireRisk/${r.externalId}: invalid ISO timestamp`);
    if (!r.statusSource || r.statusSource.official !== true) errors.push(`wildfireRisk/${r.externalId}: elevated record missing official statusSource`);
    if (!r.statusExplanation) {
      errors.push(`wildfireRisk/${r.externalId}: elevated record missing statusExplanation`);
    } else {
      const wc = r.statusExplanation.trim().split(/\s+/).length;
      if (wc < 15 || wc > 20) warnings.push(`wildfireRisk/${r.externalId}: statusExplanation word count ${wc} outside the target 15-20 word range`);
    }
    if (looksLikeSecret(r.externalId) || looksLikeSecret(r.sourceUrl)) errors.push(`wildfireRisk/${r.externalId}: field resembles a hardcoded credential and was rejected`);
  }
}
if (!sawSourceHealth) errors.push('No sourceHealth record observed in merged input (upstream fetch may not have run)');

return [{ json: { recordKind: 'validationResult', passed: errors.length === 0, errors, warnings } }, ...allInputs.map((r) => ({ json: r }))];

const config = $items('Set Connector Config')[0].json;
const items = $input.all().map((i) => i.json || {});
const validationResult = items.find((i) => i.recordKind === 'validationResult') || { passed: true, errors: [], warnings: [] };
const wildfireRisk = items.filter((i) => i.recordKind === 'wildfireRisk');
const sourceHealth = items.filter((i) => i.recordKind === 'sourceHealth');
const generatedAt = config.generatedAt || new Date().toISOString();
const sourceNames = sourceHealth.length
  ? sourceHealth.map((source) => source.sourceName || source.sourceId).filter(Boolean)
  : [config.attributionText || 'Météo-France Météo des Forêts'];
const sourceUrls = [config.sourceUrl].filter(Boolean);
const sourceReferences = Array.from(new Set([...sourceNames, ...sourceUrls]));
const sourceUpdatedCandidates = wildfireRisk
  .map((record) => record.startTime || record.checkedAt || null)
  .filter((value) => value && !Number.isNaN(Date.parse(value)));
const latestSourceUpdatedAt = sourceUpdatedCandidates.length
  ? sourceUpdatedCandidates.sort().slice(-1)[0]
  : (sourceHealth[0]?.fetchedAt || null);
const connectorWarnings = [
  ...sourceHealth.flatMap((source) => Array.isArray(source.warnings) ? source.warnings : []),
  ...(validationResult.warnings || []),
];
const connectorErrors = [
  ...sourceHealth.flatMap((source) => Array.isArray(source.errors) ? source.errors : []),
  ...(validationResult.errors || []),
];
const allSourceOk = sourceHealth.length > 0 && sourceHealth.every((source) => source.status === 'ok');
const anySourceFailed = sourceHealth.some((source) => source.status === 'failed' || source.status === 'credentials_blocked');
const sourceFreshness = latestSourceUpdatedAt && !Number.isNaN(Date.parse(latestSourceUpdatedAt))
  ? (Date.parse(generatedAt) - Date.parse(latestSourceUpdatedAt)) / 60000
  : 0;
const stale = Number.isFinite(sourceFreshness) ? sourceFreshness > Number(config.staleAfterMinutes || 0) : false;
const shouldPublish = validationResult.passed === true && !anySourceFailed && !stale && allSourceOk;
const contractStatus = shouldPublish
  ? (connectorWarnings.length ? 'SUCCESS_WITH_WARNINGS' : 'SUCCESS')
  : stale
    ? 'STALE_LAST_KNOWN_GOOD'
    : 'FAILED_NO_OUTPUT';

const connectorPayload = {
  connectorId: config.connectorId,
  connectorNumber: config.connectorNumber,
  connectorName: config.connectorName,
  workflowName: config.workflowName,
  workflowVersion: config.workflowVersion,
  generatedAt,
  timezone: config.timezone,
  status: anySourceFailed ? 'failed' : (validationResult.passed ? 'ok' : 'failed'),
  sources: [
    {
      sourceId: 'meteo-france-forest-weather',
      sourceName: 'Météo-France Météo des Forêts',
      endpoint: config.forestWeatherEndpoint,
      category: 'wildfire',
    },
  ],
  wildfireRisk,
  records: wildfireRisk,
  sourceHealth,
  attribution: {
    required: true,
    source: 'Météo-France Météo des Forêts',
    official: true,
  },
  validation: {
    passed: validationResult.passed,
    errors: validationResult.errors || [],
    warnings: validationResult.warnings || [],
  },
  compatibility: {
    targetMonitoringFeed: 'public/cdm-monitoring-status.json',
    mode: 'compatibility_candidate',
  },
};

const envelope = {
  schema_version: '1.0.0',
  connector_id: config.connectorId,
  connector_name: config.connectorName,
  run_id: config.connectorId + '-' + generatedAt,
  status: contractStatus,
  started_at: sourceHealth[0]?.fetchedAt || generatedAt,
  completed_at: new Date().toISOString(),
  generated_at: generatedAt,
  source_updated_at: latestSourceUpdatedAt,
  record_count: wildfireRisk.length,
  source_count: sourceHealth.length,
  sources: sourceReferences,
  data: connectorPayload,
  warnings: connectorWarnings,
  errors: connectorErrors,
  stale,
  last_known_good: {
    is_last_known_good: false,
    reason: shouldPublish
      ? 'Fresh candidate output validated and promoted from staging.'
      : 'Candidate output failed publish gating; existing final output must remain untouched.',
  },
  validation: {
    schema_valid: validationResult.passed === true,
  },
};

return [{
  json: {
    label: '04_wildfire.staging',
    targetPath: config.stagingOutputPath,
    finalPath: config.finalOutputPath,
    shouldPublish,
    contractStatus,
    sourceStatuses: sourceHealth.map((source) => source.status),
    jsonText: JSON.stringify(envelope, null, 2) + '\n',
  },
}];

const output = [];
for (const item of $input.all()) {
  const buf = Buffer.from(item.json.jsonText, 'utf8');
  const fileName = String(item.json.targetPath).split('/').pop();
  const binary = await this.helpers.prepareBinaryData(buf, fileName, 'application/json');
  output.push({ json: item.json, binary: { data: binary } });
}
return output;

const REQUIRED_STATUS = new Set(['SUCCESS', 'SUCCESS_WITH_WARNINGS', 'STALE_LAST_KNOWN_GOOD', 'FAILED_NO_OUTPUT']);
const REQUIRED_TOP_LEVEL_FIELDS = [
  'schema_version',
  'connector_id',
  'connector_name',
  'run_id',
  'status',
  'started_at',
  'completed_at',
  'generated_at',
  'source_updated_at',
  'record_count',
  'source_count',
  'sources',
  'data',
  'warnings',
  'errors',
  'stale',
  'last_known_good',
  'validation',
];

function isIso(value) {
  return typeof value === 'string' && !Number.isNaN(Date.parse(value));
}

const buildPayloadItems = $items('Build Wildfire Output Payloads');
const results = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const originalJson = buildPayloadItems[i]?.json || {};
  const mergedJson = {
    ...originalJson,
    ...(item.json || {}),
    targetPath: originalJson.targetPath || item.json?.targetPath || item.json?.fileName || 'unknown',
    finalPath: originalJson.finalPath || item.json?.finalPath || null,
    shouldPublish: originalJson.shouldPublish === true || item.json?.shouldPublish === true,
    label: originalJson.label || item.json?.label || 'unknown',
  };
  const fileName = mergedJson.targetPath || item.json?.fileName || 'unknown';
  const targetPath = mergedJson.targetPath;
  const finalPath = mergedJson.finalPath;
  const shouldPublish = mergedJson.shouldPublish === true;
  if (!item.binary || !item.binary.data) {
    results.push({ json: { label: mergedJson.label, targetPath, finalPath, shouldPublish, validJson: false, bytes: 0, error: 'No binary data read back for ' + fileName } });
    continue;
  }
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  const text = buf.toString('utf8');
  let parsed;
  try {
    parsed = JSON.parse(text);
  } catch (err) {
    results.push({ json: { label: mergedJson.label, targetPath, finalPath, shouldPublish, validJson: false, bytes: Buffer.byteLength(text, 'utf8'), error: 'Invalid JSON: ' + err.message } });
    continue;
  }

  const errors = [];
  for (const field of REQUIRED_TOP_LEVEL_FIELDS) {
    if (!(field in parsed)) errors.push('Missing top-level field ' + field);
  }
  if (parsed.schema_version !== '1.0.0') errors.push('schema_version must be 1.0.0');
  if (!REQUIRED_STATUS.has(parsed.status)) errors.push('Invalid contract status ' + parsed.status);
  for (const field of ['started_at', 'completed_at', 'generated_at']) {
    if (!isIso(parsed[field])) errors.push(field + ' must be ISO 8601 UTC');
  }
  if (parsed.source_updated_at !== null && parsed.source_updated_at !== undefined && !isIso(parsed.source_updated_at)) {
    errors.push('source_updated_at must be null or ISO 8601 UTC');
  }
  if (!Array.isArray(parsed.sources)) errors.push('sources must be an array');
  if (!Array.isArray(parsed.warnings)) errors.push('warnings must be an array');
  if (!Array.isArray(parsed.errors)) errors.push('errors must be an array');
  if (typeof parsed.record_count !== 'number') errors.push('record_count must be numeric');
  if (typeof parsed.source_count !== 'number') errors.push('source_count must be numeric');
  if (typeof parsed.stale !== 'boolean') errors.push('stale must be boolean');
  if (!parsed.last_known_good || typeof parsed.last_known_good.is_last_known_good !== 'boolean' || typeof parsed.last_known_good.reason !== 'string') {
    errors.push('last_known_good must include is_last_known_good and reason');
  }
  if (!parsed.validation || typeof parsed.validation.schema_valid !== 'boolean') {
    errors.push('validation.schema_valid must be boolean');
  }
  if (!parsed.data || typeof parsed.data !== 'object') errors.push('data must be an object');
  if (parsed.connector_id !== '04_WILDFIRE') errors.push('connector_id mismatch');
  if (parsed.connector_name !== 'CDM Wildfire Connector') errors.push('connector_name mismatch');

  results.push({
    json: {
      label: mergedJson.label,
      targetPath,
      finalPath,
      shouldPublish,
      validJson: errors.length === 0,
      bytes: Buffer.byteLength(text, 'utf8'),
      error: errors.length ? errors.join('; ') : null,
      parsedStatus: parsed.status,
      recordCount: parsed.record_count,
      sourceCount: parsed.source_count,
    },
  });
}
return results;
